package live.linghe.privateinput;
public final class RecentLearningSlotTest {
 static int checks;static void ok(boolean yes,String label){checks++;if(!yes)throw new AssertionError(label);}
 interface Work{void run()throws Exception;}static void rejects(Work work,String label)throws Exception{boolean bad=false;try{work.run();}catch(Exception expected){bad=true;}ok(bad,label);}
 public static void main(String[] args)throws Exception{String own="11111111-2222-3333-4444-555555555555",event="aaaaaaaa-bbbb-cccc-dddd-eeeeeeeeeeee",other="22222222-2222-3333-4444-555555555555";RecentLearningSlot empty=new RecentLearningSlot("",null,own,null);ok(empty.publishedEvent.isEmpty()&&empty.shouldPush("same","same",100,101),"missing server slot forces restore despite saved digest");RecentLearningSlot filled=new RecentLearningSlot(event,event,own,own);ok(filled.publishedEvent.equals(event.toUpperCase(java.util.Locale.ROOT)),"CAS pins observed event");ok(!filled.shouldPush("same","same",100,101),"unchanged fresh slot need not upload");ok(filled.shouldPush("same","same",100,86500),"24h lease refresh");ok(filled.shouldPush("new","old",100,101),"changed archive pushes");ok(filled.shouldPush("same","same",200,101),"time inconsistency refreshes");rejects(()->new RecentLearningSlot("",event,own,own),"null slot cannot carry snapshot");rejects(()->new RecentLearningSlot(event,null,own,null),"published event requires envelope");rejects(()->new RecentLearningSlot(event,event,own,other),"another sender cannot masquerade as own slot");rejects(()->new RecentLearningSlot(event,other,own,own),"event and snapshot must agree");ok(filled.accepted(event,event)&&!filled.accepted(other,event),"push verifies returned published event");System.out.println("PASS "+checks+" Android recency slot CAS checks");}
}
